#include <stdio.h>
int main(void) {
    char a[] = "listen";
    char b[] = "silent";
    int ca[26] = {0}, cb[26] = {0};
    for (int i = 0; a[i]; i++) ca[a[i]-'a']++;
    for (int i = 0; b[i]; i++) cb[b[i]-'a']++;
    int same = 1;
    for (int i = 0; i < 26; i++) if (ca[i] != cb[i]) same = 0;
    printf("%d\n", same);
    return 0;
}

