#include <stdio.h>
int main(void) {
    char s[] = "A man a plan a canal Panama";
    int cnt = 0;
    for (int i = 0; s[i]; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') cnt++;
        else if (s[i] >= 'A' && s[i] <= 'Z') cnt++;
    }
    printf("%d\n", cnt);
    return 0;
}

#include <stdio.h>
int main(void) {
    char s[] = "helloworld";
    int freq[26] = {0};
    for (int i = 0; s[i]; i++) freq[s[i]-'a']++;
    int max = 0; char mc = 'a';
    for (int i = 0; i < 26; i++) {
        if (freq[i] > max) { max = freq[i]; mc = (char)('a' + i); }
    }
    printf("%c %d\n", mc, max);
    return 0;
}

#include <stdio.h>
int main(void) {
    char s[] = "abc";
    for (int i = 0; s[i]; i++) {
        if (s[i] >= 'a' && s[i] <= 'z') {
            s[i] = (char)('a' + (s[i] - 'a' + 13) % 26);
        }
    }
    printf("%s\n", s);
    return 0;
}

#include <stdio.h>
int main(void) {
    char s[] = "aaabb";
    int i = 0;
    while (s[i]) {
        char c = s[i];
        int j = i;
        while (s[j] == c) j++;
        putchar(c);
        if (j - i > 1) printf("%d", j - i);
        i = j;
    }
    printf("\n");
    return 0;
}
